// Collect the output of each analytics query.
const scope = $('Get Analytics Scope').first().json;
const revenue = $('Calculate Revenue KPIs').first().json;
const orders = $('Calculate Order KPIs').first().json;
const products = $('Calculate Product KPIs').first().json;
const geography = $('Calculate Country KPIs').first().json;
const timeSeries = $('Calculate Time-Series KPIs').first().json;

// Build one consolidated analytics payload.
const payload = {
    metadata: {
        project: 'ShopPulse',
        source_dataset: 'UCI Online Retail',
        dataset_scope: '10,000-row sample',
        currency: 'GBP',
        completed_batches: Number(scope.completed_batches),
        total_transactions: Number(scope.total_transactions),

        period: {
            start: scope.first_transaction_date,
            end: scope.last_transaction_date
        },

        generated_at: new Date().toISOString()
    },

    scope,

    revenue,

    orders,

    products,

    geography,

    time_series: timeSeries
};

// Return exactly one item for downstream workflows.
return [
    {
        json: payload
    }
];
